60: export function addToJourney(label, text, { run = 0, hop = 0 } = {}) {
61:   if (lastEmitted && lastEmitted.label === label && lastEmitted.text === text) return;
62:   lastEmitted = { label, text };
63:   journeyEntries = orderJourneyEntries(journeyEntries, { label, text, run, hop }).slice(
64:     0,
