// DOCUMENTS: compare tray (B-5) — DOM-bound module inside the log-card.
// Pure slot/align logic lives in model.js (nextCompareSlots, alignCompareRows);
// this module owns only DOM: it stores verbatim copies of a run's journey
// entries at completion (immune to the journey-log 20-entry cap), renders
// the hop-aligned rows, and never mints or rewrites hop text (DL-1/DL-3).
// CHECKS: pushCompareRun and clearCompare are called only from panel.js's
// completion branch and switchStage — crowd ticks never reach here
// (counter-example pinned in e2e/compare.spec.js).
import { alignCompareRows, nextCompareSlots } from './model.js';

const slots = { a: null, b: null };
let tray = null;
let headline = null;
let rows = null;

export function initCompareTray() {
  if (tray) return;
  const logCard = document.querySelector('.log-card');
  if (!logCard) return;
  tray = ...;
  ...
  renderCompare();
}

function renderCompare() { ... }

export function pushCompareRun({ run, trace, entries }) {
  if (!tray || !Array.isArray(entries) || entries.length === 0) return;
  const label = trace?.request ?? fallbackLabel();
  const next = nextCompareSlots(slots, { run, label, hops: entries.length, entries });
  slots.a = next.a;
  slots.b = next.b;
  renderCompare();
}

function fallbackLabel() {
  const method = document.getElementById('req-method');
  const input = document.getElementById('url-input');
  return `${method?.value ?? 'GET'} ${input?.value ?? ''}`.trim();
}

export function clearCompare() {
  slots.a = null;
  slots.b = null;
  renderCompare();
}
```

