describe('compare tray model', () => {
  const runOf = (run, hops, label = 'GET /about') => ({
    run,
    label,
    hops,
    entries: Array.from({ length: hops }, (_, i) => ({
      run,
      hop: i + 1,
      label: `hop ${i + 1}/${hops}`,
      text: `${label} · frame ${i + 1} — answered`,
    })),
  });

  it('aligns unequal 9-by-6 runs into 9 rows with rows 7-9 right side an em-dash', () => {
    const rows = alignCompareRows(runOf(1, 9), runOf(2, 6));
    expect(rows).toHaveLength(9);
    expect(rows.map((row) => row.n)).toEqual([1, 2, 3, 4, 5, 6, 7, 8, 9]);
    expect(rows.slice(6).map((row) => row.right)).toEqual(['—', '—', '—']);
    // The longer run keeps all nine of its frames — nothing drops.
    expect(rows.slice(6).map((row) => row.left)).toEqual([
      'GET /about · frame 7 — answered',
      'GET /about · frame 8 — answered',
      'GET /about · frame 9 — answered',
    ]);
  });

  it('aligns equal runs row-for-row with no em-dash', () => {
    const rows = alignCompareRows(runOf(1, 6), runOf(2, 6));
    expect(rows).toHaveLength(6);
    expect(rows.every((row) => row.left !== '—' && row.right !== '—')).toBe(true);
    expect(rows[3]).toEqual({
      n: 4,
      left: 'GET /about · frame 4 — answered',
      right: 'GET /about · frame 4 — answered',
    });
  });

  it('passes entry texts through verbatim — alignment never mutates a stored run', () => {
    const left = runOf(1, 9);
    const right = runOf(2, 6);
    const beforeLeft = JSON.stringify(left);
    const beforeRight = JSON.stringify(right);
    const rows = alignCompareRows(left, right);
    expect(JSON.stringify(left)).toBe(beforeLeft);
    expect(JSON.stringify(right)).toBe(beforeRight);
    // Every rendered cell is the byte-identical stored text.
    expect(rows[1].left).toBe(left.entries[1].text);
    expect(rows[1].right).toBe(right.entries[1].text);
  });

